  334:             eyre::bail!(
  335:                 "job {} names only {} of the {} files it failed, so a retry would leave the \
  336:                  rest; run the whole job again instead (`blit jobs save {} <name>`, then \
  337:                  `blit jobs run <name>`)",
  338:                 record.run_id,
  339:                 known.len(),
  340:                 record.files_failed,
  341:                 record.run_id
  342:             );
  343:         }
  344:     }
  345:     Ok(known
  346:         .into_iter()
  347:         .map(|(path, _)| PathBuf::from(path))
  348:         .collect())
  349: }
